{
  "framing": {
    "libro": "Manufacturing Consent",
    "autor": "Noam Chomsky & Edward S. Herman",
    "año": 1988,
    "cita_breve": "The news media serve as a system for communicating messages and symbols to the public, but they do so within the constraints of the dominant elite's interests.",
    "explicacion": "Según Chomsky y Herman, los filtros del modelo de propaganda determinan qué noticias aparecen y cómo se presentan, configurando un marco (framing) que orienta la percepción del público sobre los asuntos tratados."
  },
  "anclaje": {
    "libro": "Propaganda",
    "autor": "Edward Bernays",
    "año": 1928,
    "cita_breve": "The conscious and intelligent manipulation of the organized habits and opinions of the masses is the problem which the new profession of public relations has taken upon itself.",
    "explicacion": "Bernays describe la técnica de establecer un punto de referencia inicial (anclaje) para orientar la opinión pública; al presentar una idea dentro de un contexto previamente aceptado, se facilita la aceptación del mensaje posterior."
  }
}
